const createdFunctions=new Map;export const createFunction=t=>{let n=createdFunctions.get(t);return n||(n=new Function(`return ${t}`)(),createdFunctions.set(t,n),n)};export function stringifyFunction(t){let n=t.toString();if(n.match(/^(async )*function(\(|\s)/)||n.match(/^(async )*function\s*\*\s*/))return n;if(n.startsWith("(")||n.match(/^async\s*\(/)||n.match(/^(async)*\s*(?:[$_\p{ID_Start}])(?:[$\u200C\u200D\p{ID_Continue}])*\s*=>/u))return n;let e="function ";return n.startsWith("async ")&&(e=`async ${e}`,n=n.substring(6)),`${e}${n}`}export const interpolateFunction=(t,n)=>{let e=stringifyFunction(t);for(const[t,c]of Object.entries(n))e=e.replace(new RegExp(`PLACEHOLDER\\(\\s*(?:'${t}'|"${t}")\\s*\\)`,"g"),`(${c})`);return createFunction(e)};